		/** 
		 * Tests creating a new Lot.
		 */
		public void testCreate() throws Throwable {
			LOGGER.info( "\n======== CREATE ======== ");
			LOGGER.info( "-- Attempting to create a Lot");

			StringBuilder msg = new StringBuilder( "-- Failed to create a Lot" );

			try {            
				Lot entity = LotService.getLotInstance().createLot( generateNewEntity() );
				thePrimaryKey = entity.getLotId();
				LOGGER.info( "-- Successfully created a Lot with primary key" + thePrimaryKey );
			}
			catch (Exception e) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : " + e );

				throw e;
			}
		}

		/** 
		 * Tests reading a Lot. 
		 */
		public Lot testRead() throws Throwable {
			LOGGER.info( "\n======== READ ======== ");
			LOGGER.info( "-- Reading a previously created Lot" );

			Lot entity = null;
			StringBuilder msg = new StringBuilder( "-- Failed to read Lot with primary key" );
			msg.append( thePrimaryKey );
			
			LotFetchOneSummary fetchOneSummary = new LotFetchOneSummary( thePrimaryKey );

			try {
				entity = LotService.getLotInstance().getLot( fetchOneSummary );

				assertNotNull( entity,msg.toString() );

				LOGGER.info( "-- Successfully found Lot " + entity.toString() );
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : " + e );

				throw e;
			}
			
			return entity;
		}

		/** 
		 * Tests updating a Lot.
		 */
		public void testUpdate() throws Throwable {
			LOGGER.info( "\n======== UPDATE ======== ");
			LOGGER.info( "-- Attempting to update a Lot." );

			StringBuilder msg = new StringBuilder( "Failed to update a Lot : " );        
			Lot entity = null;

			try {            
				entity = testRead();

				assertNotNull( entity, msg.toString() );

				LOGGER.info( "-- Now updating the created Lot." );

				// for use later on...
				thePrimaryKey = entity.getLotId();

				LotService proxy = LotService.getLotInstance();            
				proxy.updateLot( entity );   

				LOGGER.info( "-- Successfully saved Lot - " + entity.toString() );
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : primarykey = " + thePrimaryKey + " : entity-" +  entity + " : " + e );

				throw e;
			}
		}

		/** 
		 * Tests deleting a Lot.
		 */
		public void testDelete() throws Throwable {
			LOGGER.info( "\n======== DELETE ======== ");
			LOGGER.info( "-- Deleting a previously created Lot." );

			try{
			    Lot entity = testRead(); 
				LotService.getLotInstance().delete( entity );

				LOGGER.info( "-- Successfully deleted Lot with primary key " + thePrimaryKey );            
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( "-- Failed to delete Lot with primary key " + thePrimaryKey );

				throw e;
			}
		}

		/**
		 * Tests getting all Lots.
		 */
		public void testGetAll() throws Throwable {    
			LOGGER.info( "======== GETALL ======== ");
			LOGGER.info( "-- Retrieving Collection of Lots:" );

			StringBuilder msg = new StringBuilder( "-- Failed to get all Lot : " );        
			List<Lot> collection  = null;

			try {
				// call the static get method on the LotService
				collection = LotService.getLotInstance().getAllLot();

				if ( collection == null || collection.size() == 0 ) {
					LOGGER.warning( unexpectedErrorMsg );
					LOGGER.warning( msg.toString() + " Empty collection returned."  );
				}
				else {
					// Now print out the values
					Lot entity = null;            
					Iterator<Lot> iter = collection.iterator();
					int index = 1;

					while( iter.hasNext() ) {
						// Retrieve the entity   
						entity = iter.next();

						assertNotNull( entity,"-- null entity in Collection." );
						assertNotNull( entity.getLotId(), "-- entity in Collection has a null primary key" );        

						LOGGER.info( " - " + String.valueOf(index) + ". " + entity.toString() );
						index++;
					}
				}
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : " + e );

				throw e;
			}
		}

